const chosenTitle = $('Show Job Selection Form').first().json["jobTitle"];
const department = $('When Application Submitted').first().json["Select Department"];

const match = $('Filter Jobs by Department').first().json.jobs.find(job =>
  job.Role === chosenTitle && job.Department === department
);

return [{ json: match || {} }];

