const department = $('When Application Submitted').first().json["Select Department"];

const filtered = $input.all().filter(item =>
  item.json.Department === department && item.json.Status === 'OPEN'
);

return [{
  json: {
    jobs: filtered.map(item => item.json),
    jobCount: filtered.length
  }
}];

